      const g2 = `M${f10(cx - rb * 1.02)} ${f10(yb - h4 * 0.18)} L${f10(cx - rb)} ${f10(yb)} A${f10(rb)} ${f10(rb * 0.3)} 0 0 0 ${f10(cx + rb)} ${f10(yb)} L${f10(cx + rb * 1.02)} ${f10(yb - h4 * 0.18)} A${f10(rb * 1.02)} ${f10(rb * 0.3)} 0 0 1 ${f10(cx - rb * 1.02)} ${f10(yb - h4 * 0.18)} Z`;
