      for (const [i, y2] of [[0, 66], [1, 59], [2, 52]]) t5.push(teller(S, 50, y2, 40 - i * 0.4, 0.36, [dunkel3(S.c, 0.04), S.c, hell3(S.c, 0.03)][i]));
