      for (const s2 of [-1, 1]) t5.push(`<ellipse cx="${50 + s2 * 19}" cy="34" rx="4" ry="2" fill="#3f342a"/>`);
      const L3 = stoff2(S, "#ece6d8", "leinen");
      t5.push(flaeche5(L3, glatt2([[22, 26, E7], [78, 26, E7], [79, 33], [74, 30.6], [64, 33], [52, 30.4], [40, 33.2], [30, 30.6], [21, 33]], true, 0.4)));
      t5.push(flaeche5(L3, glatt2([[26, 20], [40, 15], [56, 17], [72, 14], [76, 22], [72, 26, E7], [28, 26, E7]], true, 0.5), { ton: 0.05 }));
