      t5.push(`<circle cx="50" cy="52" r="36" fill="#f5f2ec"/><circle cx="50" cy="52" r="36" fill="none" stroke="#000" stroke-opacity="0.08" stroke-width="2"/>`);
      for (let i = 0; i < 12; i++) {
        const a2 = i * Math.PI / 6, r1 = i % 3 ? 31 : 28.6;
        t5.push(linie2(`M${f10(50 + Math.sin(a2) * r1)} ${f10(52 - Math.cos(a2) * r1)} L${f10(50 + Math.sin(a2) * 33.6)} ${f10(52 - Math.cos(a2) * 33.6)}`, "#2a2c30", i % 3 ? 1 : 2));
      }
      const z6 = (deg, l, w2, c = "#2a2c30") => linie2(`M50 52 L${f10(50 + Math.sin(deg * Math.PI / 180) * l)} ${f10(52 - Math.cos(deg * Math.PI / 180) * l)}`, c, w2);
      t5.push(z6(305, 18, 2.6), z6(60, 28, 1.8), z6(160, 30, 0.6, "#c8372f"), `<circle cx="50" cy="52" r="2" fill="#2a2c30"/>`);
