        const ix = x2 + l + pp2, iy = y2 + l + pp2, iw = w2 - 2 * (l + pp2), ih = h4 - 2 * (l + pp2);
        t5.push(`<rect x="${f10(ix)}" y="${f10(iy)}" width="${f10(iw)}" height="${f10(ih)}" fill="${motiv5[0]}"/>`);
