      for (const [x2, y2, r4, c] of [[30, 44, 7, "#b58866"], [44, 42, 8, "#d8c3a0"], [60, 44, 7, "#8a6a46"], [72, 46, 6, "#c9b08a"], [52, 48, 6, "#a77c52"], [36, 49, 5.6, "#e1d2b6"]]) t5.push(`<circle cx="${x2}" cy="${y2}" r="${r4}" fill="${c}"/><circle cx="${x2 - r4 * 0.3}" cy="${y2 - r4 * 0.35}" r="${f10(r4 * 0.35)}" fill="#fff" opacity="0.25"/>`);
      t5.push(linie2("M66 42 Q72 26 80 16", "#8a7a5a", 0.7), linie2("M68 42 Q76 32 88 28", "#8a7a5a", 0.7));
      for (const [x2, y2] of [[80, 16], [88, 28], [76, 24]]) t5.push(`<circle cx="${x2}" cy="${y2}" r="2.6" fill="#e3d2b0"/><circle cx="${x2}" cy="${y2}" r="1" fill="#c9a26a"/>`);
      t5.push(`<path d="M8 46 C10 62 28 72 50 72 C72 72 90 62 92 46" fill="none" stroke="${hell3(S.c, 0.25)}" stroke-width="0.8"/>`);
