      t5.push(zylinder2(S, 76, 50, 56, 18, 5.4, "#f4f2ee"), `<ellipse cx="76" cy="50" rx="13" ry="3.6" fill="none" stroke="#d6d0c4" stroke-width="0.5"/>`);
